function makeOptions(qId: string, includeOptionD = true): TestOption[] {
  const base: TestOption[] = [
    { id: `${qId}-a`, label: 'A', text: `Option A for ${qId}` },
    { id: `${qId}-b`, label: 'B', text: `Option B for ${qId}` },
    { id: `${qId}-c`, label: 'C', text: `Option C for ${qId}` },
  ]
  if (includeOptionD) {
    base.push({ id: `${qId}-d`, label: 'D', text: `Option D for ${qId}` })
  }
  return base
}

